from research_helpers import *
a=ev('https://www.vir.bio/pipeline/','Current five named therapeutic molecules; masked TCEs licensed from Sanofi, VIR-5500 co-development with Astellas. Unnamed targets not invented as molecules.')
b=ev('https://investors.vir.bio/news/news-details/2026/Vir-Biotechnology-to-Present-Expanded-Phase-2-SOLSTICE-Results-for-Elebsiran-and-Tobevibart-in-Hepatitis-Delta-at-AASLDs-The-Liver-Meeting-2026/default.aspx','October 5 2026 issuer update explicitly equates elebsiran with VIR-2218 and tobevibart with VIR-3434.')
c=ev('https://www.vir.bio/science/PRO-XTEN-platform/','Exclusive licensed field rights for oncology/infectious diseases; Amunix/Sanofi trademark, not Vir ownership claim.')
d=ev('https://www.vir.bio/about/stories/accelerating-the-next-generation-of-therapies-with-the-dAIsy-tm-AI-platform/','Proprietary in-house antibody design research platform; not external commercial software.')
e=ev('https://www.vir.bio/science/antibody-and-t-cell-engager-platform/','Issuer discovery/engineering platform and historical sotrovimab development.')
products=[p('Elebsiran','Investigational siRNA in hepatitis-delta combination trials.',a,life='development',aliases=['VIR-2218'],evidence=[a,b]),p('Tobevibart','Investigational antiviral antibody in hepatitis-delta combination trials.',a,life='development',aliases=['VIR-3434'],evidence=[a,b])]
for name,target in [('VIR-5500','PSMA'),('VIR-5818','HER2'),('VIR-5525','EGFR')]:products.append(p(name,'Investigational masked '+target+' T-cell engager.',a,life='development',roles=['developer','licensee']))
products += [p('PRO-XTEN masking platform','Protease-releasable therapeutic masking technology.',c,life='development',typ='technology',roles=['licensee']),p('dAIsY','In-house computational antibody and T-cell engager design platform.',d,life='research',typ='technology',sub='research_tools'),p('Vir antibody and T-cell engager discovery platform','Antibody discovery and engineering research platform.',e,life='research',typ='technology',sub='research_tools'),p('Sotrovimab','Historical antiviral antibody developed with GSK; current regional availability unresolved.',e)]
co=dict(company_id='cmp_2b5d726d-6d25-4703-9889-fa4a9721478e',products=products,evidence=[a,b,c,d,e],status='partial',coverage_note='Five currently named therapeutic molecules, three research/therapeutic platforms and historical sotrovimab. Combination trial arms and third-party pembrolizumab/taxanes not counted as Vir-owned molecules. Partner rights distinguished from ownership. Partial: sotrovimab aliases/current geography, historical antiviral/vaccine/HIV programmes, discontinued candidates and uncoded preclinical projects remain. Trial progress percentages not interpreted as approval probability.')
(out/'batch-0331.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
